/bin/bash -c "python -B - <<'PY'
from pathlib import Path
import json
for f in sorted(Path('.').glob('*/actions.json')):
    data=json.loads(f.read_bytes())
    print(f, data['changed'])
    for i, op in enumerate(data['operations'],1):
        def brief(v):
            if isinstance(v, str):
                return v if len(v)<=540 else v[:380]+' … '+v[-100:]
            if isinstance(v, dict):
                return {k:brief(val) for k,val in v.items()}
            if isinstance(v, list):
                return [brief(val) for val in v]
            return v
        print(i,brief(op))
PY"

